int drm_virtio_surface_create(struct drm_device *dev, void *data,
                              struct drm_file *file_priv)
{
    struct virtio_surface_create_args *args = data;
    struct virtio_surface *surface;
    int ret = -ENOMEM;

    if (!args) {
        DRM_ERROR("Invalid surface creation arguments.\n");
        return -EINVAL;
    }

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface)
        goto out;

    surface->width = args->width;
    surface->height = args->height;
    surface->format = args->format;

    ret = virtio_surface_init(dev, surface, file_priv);
    if (ret)
        goto free_surface;

    args->handle = surface->handle;

    return 0;

free_surface:
    kfree(surface);
out:
    return ret;
}

int drm_vmw_surface_create(struct drm_device *dev, void *data,
                           struct drm_file *file_priv)
{
    int ret = -EINVAL;
    struct vmw_surface_arg *arg = data;

    if (!dev || !arg || !file_priv)
        return ret;

    ret = -ENOMEM;
    struct vmw_private *dev_priv = dev->dev_private;
    struct vmw_surface *surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface)
        return ret;

    surface->dev = dev;
    surface->id = dev_priv->surface_id_counter++;
    surface->format = arg->format;
    surface->width = arg->width;
    surface->height = arg->height;
    surface->mip_levels = arg->mip_levels;

    if (!arg->backup_only) {
        struct vmw_surface_backup *backup = kzalloc(sizeof(*backup), GFP_KERNEL);
        if (!backup) {
            kfree(surface);
            return ret;
        }
        backup->size = arg->backup_size;
        backup->data = kzalloc(backup->size, GFP_KERNEL);
        if (!backup->data) {
            kfree(backup);
            kfree(surface);
            return ret;
        }
        surface->backup = backup;
    }

    ret = vmw_surface_init(dev, surface, file_priv);
    if (ret < 0) {
        if (surface->backup) {
            kfree(surface->backup->data);
            kfree(surface->backup);
        }
        kfree(surface);
        return ret;
    }

    arg->sid = surface->id;
    return 0;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct surface_creation_args *args = data;
    struct graphics_buffer_surface *surface = NULL;
    int ret = -EINVAL;

    if (!dev || !args || !file_priv) {
        return -EINVAL;
    }

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface) {
        return -ENOMEM;
    }

    ret = allocate_surface_resources(surface, args);
    if (ret) {
        kfree(surface);
        return ret;
    }

    ret = init_surface(surface, args);
    if (ret) {
        free_surface_resources(surface);
        kfree(surface);
        return ret;
    }

    ret = allocate_backup_memory(surface);
    if (ret) {
        free_surface_resources(surface);
        kfree(surface);
        return ret;
    }

    populate_surface_details(args, surface);

    drm_gem_object_handle_create(file_priv, &surface->obj, &surface->handle);

    return 0;
}

int vmwgfx_surface_create(struct drm_device *dev, void *data,
                          struct drm_file *file_priv)
{
    struct drm_vmwgfx_surface_create_arg *arg =
        (struct drm_vmwgfx_surface_create_arg *)data;
    struct vmw_private *dev_priv = dev->dev_private;
    struct ttm_buffer_object *bo = NULL;
    struct vmw_surface *surface = NULL;
    int ret = -ENOMEM;

    if (!dev || !arg || !file_priv)
        return -EINVAL;

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface)
        goto out;

    surface->dev = dev;
    surface->id = arg->surface_id;
    surface->format = arg->format;
    surface->width = arg->width;
    surface->height = arg->height;
    surface->depth = arg->depth;

    ret = vmw_surface_init(dev, surface, arg, file_priv);
    if (ret)
        goto out;

    ret = ttm_bo_init(&dev_priv->mman, &surface->backup, arg->size,
                      TTM_PL_FLAG_NO_EVICT | TTM_PL_FLAG_DMA32,
                      TTM_PAGE_SIZE_DEFAULT, 1, NULL, NULL);
    if (ret)
        goto out;

    arg->handle = ttm_bo_reference_object(&surface->backup);

    list_add(&surface->head, &dev_priv->surface_list);
    dev_priv->surface_count++;

    return 0;

out:
    if (surface) {
        if (surface->backup.ttm)
            ttm_bo_unref(&surface->backup.ttm);
        kfree(surface);
    }

    return ret;
}

